"columns":2,"rows":1,"color":"#000000","backgroundColor":"rgb(27, 43, 51)","borderColor":"rgba(255, 255, 255, 0)","borderWidth":"medium","borderStyle":"solid"},"responsiveStyle":{"desktop":{"css":{"display":"block","marginTop":"5","marginLeft":"0","marginRight":"0","marginBottom":"5","paddingTop":"50","paddingLeft":"0","paddingRight":"0","paddingBottom":"0"},"isVisible":true},"tablet":{"css":{"display":"block","marginTop":"5","marginLeft":"0","marginRight":"0","marginBottom":"5","paddingTop":"0","paddingLeft":"0","paddingRight":"0","paddingBottom":"0"},"isVisible":true},"mobile":{"css":{"display":"block","marginTop":"5","marginLeft":"0","marginRight":"0","marginBottom":"5","paddingTop":"0","paddingLeft":"0","paddingRight":"0","paddingBottom":"0"},"isVisible":true}},"id":"a92f2668-cad7-27a2-6c44-f764a9c80a7e","isHidden":false,"conditions":{"showOnlyOnCondition":true,"conditionsList":[]},"customStyle":true,"template":"component.container","selected":false}],"style":{"width":"14.285714285714286%","borderLeftWidth":"","borderBottomWidth":0},"grid":{"columns":1,"rows":1},"isRendered":true,"isRightEdge":false},{"components":[],"style":{"width":"14.285714285714286%","borderLeftWidth":"","borderBottomWidth":0},"grid":{"columns":1,"rows":1},"isRendered":true,"isRightEdge":true}]},"style":{"columns":7,"rows":1,"color":"rgb(255, 255, 255)","backgroundColor":"rgb(27, 43, 51)","borderColor":"rgba(255, 255, 255, 0)","borderWidth":"medium","borderStyle":"solid"},"responsiveStyle":{"desktop":{"css":{"display":"block","marginTop":"-7","marginLeft":"0","marginRight":"0","marginBottom":"0","paddingTop":"0","paddingLeft":"5","paddingRight":"5","paddingBottom":"0"},"isVisible":true},"tablet":{"css":{"display":"block","marginTop":"5","marginLeft":"0","marginRight":"0","marginBottom":"5","paddingTop":"0","paddingLeft":"0","paddingRight":"0","paddingBottom":"0"},"isVisible":true},"mobile":{"css":{"display":"block","marginTop":"5","marginLeft":"0","marginRight":"0","marginBottom":"5","paddingTop":"0","paddingLeft":"0","paddingRight":"0","paddingBottom":"0"},"isVisible":true}},"id":"df33bc01-64a8-33e4-c89c-de8671a37d8c","isHidden":false,"conditions":{"showOnlyOnCondition":true,"conditionsList":[]},"customStyle":true,"template":"component.container","selected":true},{"typeName":"Container","type":"container","name":"","container":true,"renderingType":"lazy","isX":false,"layout":{"sections":[{"components":[{"typeName":"HTML","type":"embedded_html","useScopedCss":false,"data":{"code":{"fields":[],"html":"<div class="lds-spinner"><div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div><div></div></div>","css":".lds-spinner {
  color: official;
  display: inline-block;
  position: fixed;
  left: 0;
  margin: 0 auto;
  right: 0;
  top: 50%;
  width: 80px;
  height: 80px;
}
.lds-spinner div {
  transform-origin: 40px 40px;
  animation: lds-spinner 1.2s linear infinite;
}
.lds-spinner div:after {
  content: " ";
  display: block;
  position: absolute;
  top: 3px;
  left: 37px;
  width: 6px;
  height: 18px;
  border-radius: 20%;
  background: #000;
}
.lds-spinner div:nth-child(1) {
  transform: rotate(0deg);
  animation-delay: -1.1s;
}
.lds-spinner div:nth-child(2) {
  transform: rotate(30deg);
  animation-delay: -1s;
}
.lds-spinner div:nth-child(3) {
  transform: rotate(60deg);
  animation-delay: -0.9s;
}
.lds-spinner div:nth-child(4) {
  transform: rotate(90deg);
  animation-delay: -0.8s;
}
.lds-spinner div:nth-child(5) {
  transform: rotate(120deg);
  animation-delay: -0.7s;
}
.lds-spinner div:nth-child(6) {
  transform: rotate(150deg);
  animation-delay: -0.6s;
}
.lds-spinner div:nth-child(7) {
  transform: rotate(180deg);
  animation-delay: -0.5s;
}
.lds-spinner div:nth-child(8) {
  transform: rotate(210deg);
  animation-delay: -0.4s;
}
.lds-spinner div:nth-child(9) {
  transform: rotate(240deg);
  animation-delay: -0.3s;
}
.lds-spinner div:nth-child(10) {
  transform: rotate(270deg);
  animation-delay: -0.2s;
}
.lds-spinner div:nth-child(11) {
  transform: rotate(300deg);
  animation-delay: -0.1s;
}
.lds-spinner div:nth-child(12) {
  transform: rotate(330deg);
  animation-delay: 0s;
}
@keyframes lds-spinner {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
","js":"/* Welcome to our javascript API 
* You have Access to the global object EMBED, 
* this object contains Methods: 
* @ getData() 
* @ onChangeData() 
* @ onSingleChangeData() 
* @ getRootElement()  - returns jQuery element 

* function useData(data) {
*	data = data || EMBED.getData(); 
*   doSomethingWithData(data); 
* }
* useData(); 
* 
* trigger change data for any change 
* EMBED.onChangeData(useData); 
* 
* trigger change data when specific field change (by field name) 
* EMBED.onSingleChangeData('fieldName', function(data) { 
